import{_ as i,a0 as l,w as r,s as c,ao as d,I as o,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"watch：定期重复Linux / Unix命令 | LCTT x X-CMD","titleTemplate":false,"description":"watch：定期重复Linux / Unix命令 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"watch：定期重复Linux / Unix命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"watch：定期重复Linux / Unix命令 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals","title":"watch：定期重复Linux / Unix命令","tag":"201507","desc":""},"relativePath":"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals.md","filePath":"[post].md"}'),s={name:"201507/20150610 watch--Repeat Linux or Unix Commands Regular Intervals.md"};function h(m,t,x,u,w,g){const a=l("Link");return r(),c("div",null,[t[13]||(t[13]=d(`<h1 id="watch-定期重复linux-unix命令" tabindex="-1">watch：定期重复Linux / Unix命令 <a class="header-anchor" href="#watch-定期重复linux-unix命令" aria-label="Permalink to “watch：定期重复Linux / Unix命令”">​</a></h1><p>服务器管理员需要维护系统并保持更新和安全。每天需要运行大量的指令。有些系统进程会记录日志。这些日志不断更新。为了检查这些更新，需要重复地执行命令。比如，为了读取一个日志文件需要使用head、tail、cat等命令。这些命令需要重复地执行。而watch命令可以用于定期地执行一个命令。</p><h3 id="watch-命令" tabindex="-1">Watch 命令 <a class="header-anchor" href="#watch-命令" aria-label="Permalink to “Watch 命令”">​</a></h3><p>watch是一个简单的命令，只有几个选项。watch命令的基本语法是：</p><pre><code>watch [-dhvt] [-n &lt;seconds&gt;] [--differences[=cumulative]] [--help] [--interval=&lt;seconds&gt;] [--no-title] [--version] &lt;command&gt;
</code></pre><p>watch命令默认每隔2秒执行后面参数给出的命令。这个时间根据的是命令执行结束到上次执行的间隔来算的。比如，watch命令可以用于监测日志更新，更新是在文件的后面追加新的内容，因此可以用tail命令来检测文件的更新（LCTT 译注：可以直接使用 <code>tail -f</code> 主动跟踪某个文件的更新，而不用使用 watch。）。这个命令会持续地运行直到你按下 <code>CTRL + C</code>回到提示符。</p><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to “例子”">​</a></h3><p>每两秒监测 errors/notices/warning 生成的情况。</p><pre><code>watch tail /var/log/messages
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/1.png" alt="tail messages"></p><p>按指定的时间间隔监测磁盘的使用率。</p><pre><code>watch df -h
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/2.png" alt="df -h"></p><p>对磁盘管理员而言，关注高I/O等待导致的磁盘操作尤其是mysql事务是很重要的。</p><pre><code>watch mysqladmin processlist
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/3.png" alt="processlist"></p><p>监测服务器负载和运行时间。</p><pre><code>watch uptime
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10.png" alt="uptime"></p><p>监测exim给用户发送通知的队列大小。</p><pre><code>watch exim -bpc
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/9.png" alt="exim -bpc"></p><h3 id="_1-指定延迟" tabindex="-1">1) 指定延迟 <a class="header-anchor" href="#_1-指定延迟" aria-label="Permalink to “1) 指定延迟”">​</a></h3><pre><code>watch [-n &lt;seconds&gt;] &lt;command&gt;
</code></pre><p>命令默认运行的时间间隔可用-n改变，下面的命令会在5秒后运行后面的命令：</p><pre><code>watch -n 5 date
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/4b.png" alt="date 5 seconds"></p><h3 id="_2-连续输出比较" tabindex="-1">2) 连续输出比较### <a class="header-anchor" href="#_2-连续输出比较" aria-label="Permalink to “2) 连续输出比较###”">​</a></h3><p>如果你使用-d选项，它会累次地高亮第一次和下一次命令之间输出的差别。</p><pre><code>watch [-d or --differences[=cumulative]] &lt;command&gt;
</code></pre><p>例子 1，用下面的命令连续地输出时间并观察高亮出来的不同部分。</p><pre><code>watch -n 15 -d date
</code></pre><p>第一次执行date的输出会被记录，15秒后会重复运行命令。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/6.png" alt="Difference A"></p><p>在下一次执行时，可以看到输出除了被高亮的秒数从14到29之外其他的都一样。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/6b.png" alt="Difference A"></p><p>例子 2，让我们来体验一下两个连续的“uptime”命令输出的不同。</p><pre><code>watch -n 20 -d uptime
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10.png" alt="uptime"></p><p>现在列出了时间和3个负载快照之间的不同。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/10b.png" alt="10b"></p><h3 id="_3-不带标题输出" tabindex="-1">3) 不带标题输出 <a class="header-anchor" href="#_3-不带标题输出" aria-label="Permalink to “3) 不带标题输出”">​</a></h3><p>如果你不希望显示更多关于延迟和实际命令的信息可以使用-t选项。</p><pre><code>watch [-t or --no-title] &lt;command&gt;
</code></pre><p>让我们看下下面例子命令的输出：</p><pre><code>watch -t date
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/7t.png" alt="watch without title"></p><h3 id="watch-帮助" tabindex="-1">Watch 帮助 <a class="header-anchor" href="#watch-帮助" aria-label="Permalink to “Watch 帮助”">​</a></h3><p>可以在ssh中输入下面的命令来得到watch的简要帮助。</p><pre><code>watch -h [or --help]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/8h.png" alt="watch help"></p><h3 id="watch-版本" tabindex="-1">Watch 版本 <a class="header-anchor" href="#watch-版本" aria-label="Permalink to “Watch 版本”">​</a></h3><p>在ssh终端中运行下面的命令来检查watch的版本。</p><pre><code>watch -v [--version]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/11.png" alt="version"></p><p><strong>不足</strong></p><p>不幸的是，在终端大小调整时，屏幕不能在下次运行前重画。所有用--difference高亮的内容也会在更新时丢失。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>watch对系统管理员而言是一个非常强大的工具，因为它可以用于监控、日志、运维、性能和系统运行时的吞吐量。人们可以非常简单地格式化和推延watch的输出。任何Linux命令/程序或脚本可以按照所需监测和连续输出。</p><hr>`,60)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"http://linoxide.com/linux-command/linux-watch-command/"},{default:p(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-watch-command/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),n(a,{href:"http://linoxide.com/author/arunrz/"},{default:p(()=>[...t[2]||(t[2]=[e("Aun Raza",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:p(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const L=i(s,[["render",h]]);export{T as __pageData,L as default};
